package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; import java.time.*; @Service public class AppointmentService{private final AppointmentRepository r;private final DoctorRepository dr;private final PatientRepository pr;public AppointmentService(AppointmentRepository r,DoctorRepository dr,PatientRepository pr){this.r=r;this.dr=dr;this.pr=pr;} private Appointment find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Appointment not found"));} private AppointmentDTO dto(Appointment e){return AppointmentDTO.builder().id(e.getId()).appointmentDate(e.getAppointmentDate()).reason(e.getReason()).status(e.getStatus()).doctorId(e.getDoctor().getId()).patientId(e.getPatient().getId()).build();} private void apply(Appointment e,AppointmentDTO d){if(d.getAppointmentDate().isBefore(LocalDateTime.now()))throw new BusinessException("Appointment date must be in the future");Doctor doc=dr.findById(d.getDoctorId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Doctor not found"));Patient p=pr.findById(d.getPatientId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Patient not found"));e.setAppointmentDate(d.getAppointmentDate());e.setReason(d.getReason());e.setStatus(d.getStatus());e.setDoctor(doc);e.setPatient(p);} public AppointmentDTO create(AppointmentDTO d){Appointment e=new Appointment();apply(e,d);return dto(r.save(e));} public List<AppointmentDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public AppointmentDTO get(Long id){return dto(find(id));} public AppointmentDTO update(Long id,AppointmentDTO d){Appointment e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Appointment e=find(id);e.setIsActive(false);r.save(e);} public List<AppointmentDTO> doctorDate(Long id,LocalDate date){return r.activeForDoctorOnDate(id,date).stream().map(this::dto).toList();} public long totalForDoctor(Long id){return r.countByDoctorIdAndIsActiveTrue(id);}}
